30	 * Slug lookup for the `[orgSlug]` routes. A closed workspace keeps its slug
31	 * and is returned like any other row; the caller sees `archivedAt` and
32	 * decides what to render.
33	 */
34	export async function findOrgBySlug(slug: string): Promise<Organization | null> {
35	  const row = getDb()
36	    .select()
37	    .from(organizations)
38	    .where(eq(organizations.slug, slug))
39	    .get();
40	  return row ? toOrganization(row) : null;
41	}
