43	/** Every org the user still holds a live membership in. */
44	export async function listOrgsForUser(
45	  userId: UserId,
46	): Promise<readonly Organization[]> {
47	  const rows = getDb()
48	    .select({ org: organizations })
49	    .from(members)
50	    .innerJoin(organizations, eq(organizations.id, members.orgId))
51	    .where(and(eq(members.userId, userId), isNull(members.archivedAt)))
52	    .all();
53	
54	  return rows.map((row) => toOrganization(row.org));
55	}
56	
57	/**
58	 * Creates the org row. The slug is de-duplicated here rather than in the
59	 * service so a race on the unique index still resolves to a usable slug.
60	 */
61	export async function insertOrg(
62	  input: CreateOrganizationInput,
63	  ownerId: UserId,
64	): Promise<Organization> {
65	  const taken = await listTakenOrgSlugs(input.slug);
66	  const slug = uniqueSlug(input.slug, taken);
67	  const stamp = toIsoTimestamp(new Date());
68	
69	  const row = getDb()
70	    .insert(organizations)
71	    .values({
72	      id: newId(),
73	      name: input.name,
74	      slug,
75	      ownerId,
76	      plan: input.plan,
77	      logoUrl: null,
78	      trialEndsAt: null,
79	      createdAt: stamp,
80	      updatedAt: stamp,
81	    })
82	    .returning()
83	    .get();
84	
85	  return toOrganization(row);
86	}
